contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: take an address for distributeAddress and an amount to mint into this contract
    function run(address receiver) public payable {
        require(receiver != address(0));

        // We cannot call internal mint on C; but on construction C minted initial supply to its deployer (which is this test's deployer of C).
        // We will act as caller for onlyOwner/onlyCaller functions by using c's public methods that are available to caller (this contract is the deployer of C per harness description).
        // Set caller (cfo) to this contract so we can call distributeToken. First, setCaller requires onlyOwner; this contract deployed C so it is owner.
        c.setCaller(address(this));

        // Set distribute address via onlyCaller (now this contract).
        c.setDistributeAddress(receiver);

        // Query contract token balance before attempting periodic distribution
        uint256 beforeBalance = c.balanceOf(address(c));
        uint256 distributeAmount = 2000 * 1e18; // matches C.distributeAmount

        // Ensure there is enough balance in c for distribution; if not, skip transfer attempt by not calling distributeTokenPeriodic
        // But we must exercise the function for proof, so we only call when balance >= distributeAmount
        bool called = false;
        if (beforeBalance >= distributeAmount) {
            // call periodic distribution; it may revert if timing condition fails. We capture revert.
            bool reverted;
            try c.distributeTokenPeriodic() {
                reverted = false;
            } catch {
                reverted = true;
            }

            // After the call (or revert), read after state
            uint256 afterBalance = c.balanceOf(address(c));
            uint256 receiverBalance = c.balanceOf(receiver);
            uint256 newInitTime = 0;
            // initTime is not public; but we can infer timing behavior: if call succeeded, contract transferred distributeAmount to receiver and c's balance decreased by that amount.

            if (!reverted) {
                // If it did not revert then balances must have changed accordingly
                assert(beforeBalance - afterBalance == distributeAmount && receiverBalance >= distributeAmount);
            } else {
                // If reverted, then no transfer happened: balances unchanged
                assert(beforeBalance == afterBalance && receiverBalance < distributeAmount);
            }

            called = true;
        }

        // Final general assertion: Either we didn't call because insufficient balance, or if we called then the observed behavior matches the transfer/no-transfer depending on revert.
        assert(address(this) != address(0) && (beforeBalance < distributeAmount || called));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    // params: addr to set as distributeAddress (must be non-zero) and an address that will become cfo (caller)
    function run(address receiver, address caller) public payable {
        require(receiver != address(0));
        require(caller != address(0));

        // make this contract the caller (cfo) by having the owner set it; the deployer of C is the test harness, not this contract,
        // but per problem statement this contract constructed C and thus is owner. Set caller to this contract first.
        // State-changing calls on c must be top-level statements.
        c.setCaller(address(this));

        // Now use onlyCaller functions by using this contract (we are cfo). Set the distributeAddress to 'receiver'.
        c.setDistributeAddress(receiver);

        // Read balances before attempting distribution
        uint256 beforeCBalance = c.balanceOf(address(c));
        uint256 beforeReceiverBalance = c.balanceOf(receiver);
        uint256 distributeAmount = 2000 * 1e18;

        // Attempt the distribution and capture whether it reverted.
        bool reverted;
        try c.distributeToken() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read balances after the call
        uint256 afterCBalance = c.balanceOf(address(c));
        uint256 afterReceiverBalance = c.balanceOf(receiver);

        // General invariant asserted: if call succeeded then exactly distributeAmount moved from c to receiver; if it reverted then balances unchanged.
        assert((!reverted && beforeCBalance >= distributeAmount && beforeCBalance - afterCBalance == distributeAmount && afterReceiverBalance - beforeReceiverBalance == distributeAmount) || (reverted && beforeCBalance == afterCBalance && beforeReceiverBalance == afterReceiverBalance));
    }

    receive() external payable {}
